// Station logic: reservations, parking sessions, LCD and gate.
// Inputs
//   bikestation/slotN/state  ~5 Hz from the occupancy functions
//   a tap after the db lookup: msg.tap, msg.payload = [{user_id, display_name, paired, parked_slot}]
//                              (msg.error set and no rows when the lookup failed)
//   station/tick             every 10 s, expires reservations when no sensor reports
// Outputs: 1 LCD steps, 2 slot state, 3 gate, 4 session sql
const SLOTS = 4;
const RESERVE_MS = 5 * 60 * 1000;
const STABLE = 5;          // equal readings (~1 s) before a slot counts as changed

const occ = flow.get('occupiedStable') || {};      // slot -> true/false, debounced
const res = flow.get('reservations') || {};        // slot -> {uid, userId, name, at}
const seen = context.get('seen') || {};            // slot -> {cand, n}

const lcdOut = [], stateOut = [], gateOut = [], sqlOut = [];
const sql = (query, params) => sqlOut.push({ query: query, params: params });
const lcd = (steps) => { lcdOut.length = 0; lcdOut.push({ steps: steps }); };
const IDLE = { l1: 'Willkommen!', l2: 'Bitte scannen' };
const later = (step, at) => Object.assign({}, step, { at: at });

// the LCD only has ASCII
function ascii(s) {
    return String(s || '')
        .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue')
        .replace(/Ä/g, 'Ae').replace(/Ö/g, 'Oe').replace(/Ü/g, 'Ue').replace(/ß/g, 'ss')
        .replace(/[^\x20-\x7e]/g, '').trim();
}
const hello = (name) => name ? { l1: 'Hallo ' + name.slice(0, 9), l2: 'Willkommen!' } : { l1: 'Hallo!', l2: 'Willkommen!' };
const stateOf = (slot) => occ[slot] ? 'occupied' : (res[slot] ? 'reserved' : 'free');
const publishState = (slot) => stateOut.push({ topic: 'bikestation/slot' + slot + '/state', payload: stateOf(slot), retain: true });

function expireOld() {
    const now = Date.now();
    for (const k of Object.keys(res)) {
        if (now - res[k].at > RESERVE_MS) {
            delete res[k];
            sql("UPDATE parking_sessions SET status = 'expired', ended_at = now() WHERE slot = $1 AND status = 'reserved'", [Number(k)]);
            publishState(k);
        }
    }
}

if (msg.topic === 'station/tick') {
    expireOld();
}
else if (msg.topic && msg.topic.startsWith('bikestation/slot')) {
    const slot = Number(msg.topic.split('/')[1].replace('slot', ''));
    const isOcc = String(msg.payload).trim().toLowerCase() === 'occupied';
    const s = seen[slot] || { cand: null, n: 0 };
    if (s.cand === isOcc) s.n++; else { s.cand = isOcc; s.n = 1; }
    seen[slot] = s;

    if (s.n >= STABLE && occ[slot] !== isOcc) {
        const before = occ[slot];
        occ[slot] = isOcc;
        if (isOcc && res[slot]) {
            // the reserved bike has arrived
            const r = res[slot];
            delete res[slot];
            sql("UPDATE parking_sessions SET status = 'parked', parked_at = now() WHERE slot = $1 AND status = 'reserved'", [slot]);
            lcd([{ l1: 'Secured: Slot ' + slot, l2: r.name ? 'Danke ' + r.name.slice(0, 10) : 'Danke!', at: 0 }, later(IDLE, 10000)]);
        } else if (!isOcc && before === true) {
            // a bike has left
            sql("UPDATE parking_sessions SET status = 'done', ended_at = now() WHERE slot = $1 AND status = 'parked'", [slot]);
        }
    }
    expireOld();
}
else if (msg.tap) {
    const t = msg.tap;
    const row = Array.isArray(msg.payload) && msg.payload[0] ? msg.payload[0] : {};
    const name = ascii(row.display_name);

    if (row.paired) {
        lcd([{ l1: 'Chip verknuepft', l2: name ? 'Hallo ' + name.slice(0, 10) : '', at: 0 }, later(IDLE, 10000)]);
    } else {
        const mine = Object.keys(res).find((k) => res[k].uid === t.uid || (row.user_id && res[k].userId === row.user_id));
        const action = t.action || (row.parked_slot ? 'pickup' : 'park');

        if (action === 'pickup') {
            lcd([later(hello(name), 0),
                 { l1: row.parked_slot ? 'Rad in Slot ' + row.parked_slot : 'Gate ist offen', l2: 'Gute Fahrt!', at: 2000 },
                 later(IDLE, 12000)]);
            gateOut.push({ payload: 'open' });
        } else if (mine) {
            // already has a reservation: show it again and give it a fresh 5 min
            res[mine].at = Date.now();
            sql("UPDATE parking_sessions SET expires_at = now() + make_interval(secs => $2) WHERE slot = $1 AND status = 'reserved'", [Number(mine), RESERVE_MS / 1000]);
            lcd([later(hello(name), 0), { l1: 'Park at Slot ' + mine, l2: 'Gate ist offen', at: 2000 }, later(IDLE, 12000)]);
            gateOut.push({ payload: 'open' });
        } else {
            let free = null;
            for (let i = 1; i <= SLOTS; i++) { if (!occ[i] && !res[i]) { free = i; break; } }
            if (!free) {
                lcd([later(hello(name), 0), { l1: 'Station Full!', l2: 'Kein Platz frei', at: 2000 }, later(IDLE, 12000)]);
            } else {
                res[free] = { uid: t.uid, userId: row.user_id || null, name: name, at: Date.now() };
                publishState(free);
                sql("WITH stale AS (UPDATE parking_sessions SET status = 'expired', ended_at = now() WHERE slot = $3 AND status = 'reserved') " +
                    "INSERT INTO parking_sessions (uid, user_id, slot, status, reserved_at, expires_at) " +
                    "VALUES ($1, $2, $3, 'reserved', now(), now() + make_interval(secs => $4))",
                    [t.uid, row.user_id || null, free, RESERVE_MS / 1000]);
                lcd([later(hello(name), 0), { l1: 'Park at Slot ' + free, l2: 'Gate ist offen', at: 2000 }, later(IDLE, 12000)]);
                gateOut.push({ payload: 'open' });
            }
        }
    }
}

flow.set('occupiedStable', occ);
flow.set('reservations', res);
context.set('seen', seen);
return [lcdOut, stateOut, gateOut, sqlOut];

