// distance -> slot state. While this slot holds the live reservation we
// publish 'reserved' rather than 'free': this function republishes ~5x per
// second, so a plain 'free' would overwrite the reservation set by
// the station logic within one cycle and the LED would never settle on the
// reserved blink.
var SLOT = '1';
var dist = parseFloat(msg.payload);
var distMsg = { topic: msg.topic, payload: dist };
var occupied = !isNaN(dist) && dist < 5;
var reservations = flow.get('reservations') || {};
msg.payload = occupied ? 'occupied'
           : (reservations[SLOT] ? 'reserved' : 'free');
msg.topic = 'bikestation/slot' + SLOT + '/state';
msg.retain = true;
return [msg, distMsg];

// distance -> slot state. While this slot holds the live reservation we
// publish 'reserved' rather than 'free': this function republishes ~5x per
